"use client";

import React, { useEffect, useState, useMemo } from "react";
import { useParams } from "next/navigation";
import { aiService } from "@/services/ai.service";
import { AIConfig, Tone, Language } from "@/types";
import { Button } from "@/components/ui/Button";
import { Settings2, Save, CheckCircle2, Loader2, Sparkles, MessageSquareWarning, Search } from "lucide-react";

const TONES: Tone[] = ["friendly", "professional", "formal", "casual"];

export default function AiPage() {
  const { projectId } = useParams<{ projectId: string }>();
  const [config, setConfig] = useState<AIConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [langSearch, setLangSearch] = useState("");
  const [langDropdownOpen, setLangDropdownOpen] = useState(false);

  useEffect(() => {
    aiService.get(projectId).then(c => { setConfig(c); setLoading(false); });
  }, [projectId]);

  // Generate dynamic language list using Intl API
  const ALL_LANGS = useMemo(() => {
    try {
      const displayNames = new Intl.DisplayNames(['en'], { type: 'language' });
      // A more comprehensive list of common language codes
      const commonCodes = [
        'id', 'en', 'es', 'fr', 'de', 'ja', 'ko', 'zh', 'ar', 'hi', 'ru', 'pt', 'it', 'tr', 'nl', 
        'vi', 'th', 'ms', 'tl', 'sv', 'pl', 'el', 'he', 'da', 'fi', 'no', 'cs', 'ro', 'hu'
      ];
      return Array.from(new Set(commonCodes.map(code => displayNames.of(code) || code))).sort();
    } catch {
      return ["Indonesian", "English", "Spanish", "French", "German", "Japanese", "Korean", "Chinese"];
    }
  }, []);

  const filteredLangs = ALL_LANGS.filter(l => l.toLowerCase().includes(langSearch.toLowerCase()));

  function update(field: keyof AIConfig, value: unknown) {
    setConfig(prev => prev ? { ...prev, [field]: value } : prev);
  }

  async function handleSave() {
    if (!config) return;
    setSaving(true);
    await aiService.save(config);
    setSaving(false);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  }

  if (loading) return <div className="flex justify-center py-24"><Loader2 className="w-7 h-7 animate-spin text-accent" /></div>;
  if (!config) return null;

  return (
    <div className="flex flex-col gap-6 w-full pb-10 h-full">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-text-primary mb-1">AI Configuration</h1>
          <p className="text-text-secondary text-sm">Design your assistant's personality, boundaries, and generation behavior.</p>
        </div>
        <Button variant="primary" icon={saved ? <CheckCircle2 className="w-4 h-4" /> : <Save className="w-4 h-4" />} onClick={handleSave} disabled={saving}>
          {saving ? "Saving..." : saved ? "Saved!" : "Save Configuration"}
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 flex-1 items-start">
        <div className="lg:col-span-2 flex flex-col gap-6">
          {/* Section 1: Core Identity */}
          <div className="bg-bg-surface border border-border-default rounded-xl overflow-hidden shadow-sm">
            <div className="bg-bg-elevated px-6 py-4 border-b border-border-default flex items-center gap-3">
              <Sparkles className="w-5 h-5 text-accent" />
              <h3 className="font-semibold text-text-primary">Core Identity & Output Style</h3>
            </div>
            <div className="p-6 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="md:col-span-1">
                   <label className="block text-sm font-semibold text-text-secondary mb-1">Assistant Name</label>
                   <input value={config.assistantName} onChange={e => update("assistantName", e.target.value)} className="w-full px-4 py-2.5 bg-bg-elevated border border-border-strong rounded-lg text-text-primary focus:border-accent focus:ring-1 focus:ring-accent/30 outline-none text-sm font-semibold transition-all shadow-inner" />
                 </div>
                 
                 <div className="md:col-span-1 relative">
                   <label className="block text-sm font-semibold text-text-secondary mb-1">Primary Language</label>
                   
                   {/* Custom Searchable Dropdown */}
                   <div className="relative">
                      <div 
                        className="w-full px-4 py-2.5 bg-bg-elevated border border-border-strong rounded-lg text-sm text-text-primary cursor-pointer flex justify-between items-center shadow-inner hover:border-accent/50 transition-colors"
                        onClick={() => setLangDropdownOpen(!langDropdownOpen)}
                      >
                        <span className="truncate">{config.language}</span>
                        <Search className="w-4 h-4 text-text-muted shrink-0" />
                      </div>
                      
                      {langDropdownOpen && (
                        <div className="absolute top-full left-0 right-0 mt-2 bg-bg-surface border border-border-default rounded-lg shadow-xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                          <div className="p-2 border-b border-border-subtle bg-bg-elevated">
                            <div className="relative">
                              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-text-muted" />
                              <input 
                                autoFocus
                                value={langSearch} 
                                onChange={e => setLangSearch(e.target.value)} 
                                placeholder="Search languages..." 
                                className="w-full pl-8 pr-3 py-1.5 bg-bg-base border border-border-strong rounded text-xs text-text-primary outline-none focus:border-accent"
                              />
                            </div>
                          </div>
                          <div className="max-h-48 overflow-y-auto">
                            {filteredLangs.length === 0 ? (
                               <div className="px-4 py-3 text-xs text-text-muted text-center">No languages found</div>
                            ) : filteredLangs.map(l => (
                              <div 
                                key={l} 
                                className={`px-4 py-2 text-sm cursor-pointer hover:bg-bg-hover transition-colors ${config.language === l ? 'bg-accent/10 text-accent font-medium' : 'text-text-primary'}`}
                                onClick={() => { update("language", l as Language); setLangDropdownOpen(false); setLangSearch(""); }}
                              >
                                {l}
                              </div>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>
                   
                   {langDropdownOpen && <div className="fixed inset-0 z-40" onClick={() => setLangDropdownOpen(false)}></div>}
                 </div>

                 <div className="md:col-span-1">
                   <label className="block text-sm font-semibold text-text-secondary mb-1">Tone & Voice</label>
                   <select value={config.tone} onChange={e => update("tone", e.target.value as Tone)} className="w-full px-4 py-2.5 bg-bg-elevated border border-border-strong rounded-lg text-text-primary focus:border-accent focus:ring-1 focus:ring-accent/30 outline-none text-sm capitalize transition-all shadow-inner">
                     {TONES.map(t => <option key={t} value={t}>{t}</option>)}
                   </select>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-border-subtle">
                 <div>
                   <label className="block text-sm font-semibold text-text-secondary mb-1">LLM Model</label>
                   <select value={config.providerModel || "gpt-4o-mini"} onChange={e => update("providerModel", e.target.value)} className="w-full px-4 py-2.5 bg-bg-elevated border border-border-strong rounded-lg text-text-primary focus:border-accent focus:ring-1 focus:ring-accent/30 outline-none text-sm transition-all shadow-inner">
                     <option value="gpt-4o">OpenAI GPT-4o</option>
                     <option value="gpt-4o-mini">OpenAI GPT-4o-mini (Faster)</option>
                     <option value="claude-3-5-sonnet">Anthropic Claude 3.5 Sonnet</option>
                     <option value="gemini-1.5-pro">Google Gemini 1.5 Pro</option>
                   </select>
                 </div>
                 
                 <div>
                   <label className="block text-sm font-semibold text-text-secondary mb-1">Provider API Key (BYOK)</label>
                   <input type="password" value={config.providerApiKey || ""} onChange={e => update("providerApiKey", e.target.value)} placeholder="e.g. sk-proj-... (Optional)" className="w-full px-4 py-2.5 bg-bg-elevated border border-border-strong rounded-lg text-text-primary focus:border-accent focus:ring-1 focus:ring-accent/30 outline-none text-sm transition-all shadow-inner placeholder:text-text-muted" />
                 </div>
              </div>
              
              <div>
                <div className="flex items-end justify-between mb-1">
                   <label className="block text-sm font-semibold text-text-secondary">Global System Instructions</label>
                   <span className="text-[10px] uppercase text-text-muted font-bold tracking-widest hidden sm:inline-block">Base Prompt Context</span>
                </div>
                <p className="text-xs text-text-muted mb-2">Define rules, boundaries, and specific behaviors that apply to every response.</p>
                <textarea rows={6} value={config.systemInstructions} onChange={e => update("systemInstructions", e.target.value)} className="w-full px-4 py-3 bg-bg-elevated border border-border-strong rounded-lg text-text-primary focus:border-accent focus:ring-1 focus:ring-accent/30 outline-none resize-none text-sm leading-relaxed transition-all shadow-inner" />
              </div>
            </div>
          </div>

          {/* Section 2: Retrieval & Fallback */}
          <div className="bg-bg-surface border border-border-default rounded-xl overflow-hidden shadow-sm">
            <div className="bg-bg-elevated px-6 py-4 border-b border-border-default flex items-center gap-3">
              <Settings2 className="w-5 h-5 text-text-secondary" />
              <h3 className="font-semibold text-text-primary">Retrieval Engine (RAG) Setup</h3>
            </div>
            
            <div className="p-6 space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div>
                  <div className="flex justify-between mb-2">
                    <label className="block text-sm font-semibold text-text-secondary">Chunk Threshold</label>
                    <span className="text-xs bg-bg-elevated px-2 py-0.5 rounded border border-border-strong font-mono">{Math.round(config.retrievalThreshold * 100)}% Match</span>
                  </div>
                  <input type="range" min="30" max="100" value={Math.round(config.retrievalThreshold * 100)} onChange={e => update("retrievalThreshold", parseInt(e.target.value) / 100)} className="w-full accent-accent cursor-pointer" />
                  <p className="text-[11px] text-text-muted mt-2">Only retrieve knowledge chunks that match the query intent at or above this percentage.</p>
                </div>
                <div>
                  <div className="flex justify-between mb-2">
                    <label className="block text-sm font-semibold text-text-secondary">Top-K Injection</label>
                    <span className="text-xs bg-bg-elevated px-2 py-0.5 rounded border border-border-strong font-mono">{config.retrievalTopK} Chunks</span>
                  </div>
                  <input type="range" min="1" max="10" value={config.retrievalTopK} onChange={e => update("retrievalTopK", parseInt(e.target.value))} className="w-full accent-accent cursor-pointer" />
                  <p className="text-[11px] text-text-muted mt-2">Maximum number of text chunks injected into the prompt context per request.</p>
                </div>
              </div>

              <div className="pt-4 border-t border-border-subtle">
                <div className="flex flex-col sm:flex-row items-start gap-4">
                  <div className="w-10 h-10 rounded-full bg-status-warning/10 flex items-center justify-center shrink-0 hidden sm:flex">
                    <MessageSquareWarning className="h-5 w-5 text-status-warning" />
                  </div>
                  <div className="flex-1 w-full">
                     <label className="block text-sm font-semibold text-text-secondary mb-1">Fallback Message</label>
                     <p className="text-xs text-text-muted mb-2">Played when the AI cannot answer based on knowledge base or guardrails.</p>
                     <input value={config.fallbackMessage} onChange={e => update("fallbackMessage", e.target.value)} className="w-full px-4 py-2.5 bg-status-warning/5 border border-status-warning/20 rounded-lg text-status-warning focus:border-status-warning outline-none text-sm placeholder:text-status-warning/40 shadow-inner" />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Section 3: Visualization Sidebar */}
        <div className="bg-bg-surface border border-border-default rounded-xl p-6 shadow-sm">
          <div className="mb-6 border-b border-border-subtle pb-4 text-center lg:text-left">
            <h3 className="font-semibold text-text-primary text-lg">Prompt Anatomy Preview</h3>
            <p className="text-text-muted text-xs mt-1 leading-relaxed">This is exactly how INFRIA combines your settings to construct the API payload before sending it to the LLM core.</p>
          </div>
          
          <div className="space-y-4 relative px-2">
             <div className="absolute left-[26px] -translate-x-1/2 top-6 bottom-10 w-0.5 bg-border-strong z-0"></div>

             {[
               { id: 1, name: "System Config", val: `"${config.systemInstructions.slice(0, 30)}..." + Tone: ${config.tone} + Lang: ${config.language}`, color: "accent", state: true },
               { id: 2, name: "Available Functions", val: config.functionCallingEnabled ? "JSON Schema array from Function registry" : "Disabled", color: config.functionCallingEnabled ? "status-success" : "text-muted", state: config.functionCallingEnabled },
               { id: 3, name: "Realtime Context", val: "User metadata & session environment injected via SDK", color: "text-secondary", state: true, dim: true },
               { id: 4, name: "RAG Injection", val: config.knowledgeEnabled ? `Top ${config.retrievalTopK} chunks (ΓëÑ${Math.round(config.retrievalThreshold * 100)}%) pulled query dynamically` : "Disabled", color: config.knowledgeEnabled ? "status-warning" : "text-muted", state: config.knowledgeEnabled },
             ].map(step => (
                <div key={step.id} className={`relative flex gap-4 z-10 ${step.state ? 'opacity-100' : 'opacity-40 grayscale'} ${step.dim ? 'opacity-70' : ''}`}>
                  <div className={`w-9 h-9 rounded-full bg-${step.color}/10 border border-${step.color}/30 text-${step.color} flex items-center justify-center font-bold text-sm shrink-0 shadow-sm relative`}>
                     {step.id}
                     <div className="absolute -inset-1 rounded-full border border-current opacity-10"></div>
                  </div>
                  <div className={`flex-1 bg-bg-elevated border border-border-default rounded-lg p-3 ${!step.state && 'bg-bg-base border-dashed'}`}>
                     <h4 className={`text-[11px] font-bold uppercase tracking-wider mb-0.5 ${step.state ? 'text-text-primary' : 'text-text-muted'}`}>{step.name}</h4>
                     <p className="text-xs text-text-muted leading-relaxed line-clamp-2">{step.val}</p>
                  </div>
                </div>
             ))}
          </div>
          
          <div className="my-6 border-b border-border-subtle" />

          <div className="bg-bg-base p-4 rounded-xl border border-border-strong/50 flex flex-col gap-3 shadow-inner">
             <label className="flex items-center gap-3 text-sm text-text-secondary cursor-pointer hover:text-text-primary transition-colors">
               <input type="checkbox" checked={config.knowledgeEnabled} onChange={e => update("knowledgeEnabled", e.target.checked)} className="w-[18px] h-[18px] rounded accent-accent" />
               <span className="font-semibold text-text-primary">Enable RAG Engine</span>
             </label>
             <label className="flex items-center gap-3 text-sm text-text-secondary cursor-pointer hover:text-text-primary transition-colors">
               <input type="checkbox" checked={config.functionCallingEnabled} onChange={e => update("functionCallingEnabled", e.target.checked)} className="w-[18px] h-[18px] rounded accent-accent" />
               <span className="font-semibold text-text-primary">Enable Function Calling</span>
             </label>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { functionService } from "@/services/function.service";
import { ConsoleFunction, CreateFunctionInput, FunctionParameter } from "@/types";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { EmptyState } from "@/components/ui/EmptyState";
import { Zap, Plus, Trash2, Loader2, ChevronDown, ChevronUp, X, Search, ArrowUpDown } from "lucide-react";

type Param = { key: string; type: string; description: string };

const TYPE_OPTIONS = ["string", "number", "boolean", "object", "array"];

export default function FunctionsPage() {
  const { projectId } = useParams<{ projectId: string }>();
  const [fns, setFns] = useState<ConsoleFunction[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAdding, setIsAdding] = useState(false);
  const [saving, setSaving] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Table Controls
  const [searchQuery, setSearchQuery] = useState("");
  const [sortField, setSortField] = useState<"name" | "status">("name");
  const [sortAsc, setSortAsc] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;

  // Form state
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [requiresAuth, setRequiresAuth] = useState(false);
  const [requiresConfirmation, setRequiresConfirmation] = useState(false);
  const [params, setParams] = useState<Param[]>([{ key: "", type: "string", description: "" }]);

  useEffect(() => {
    loadData();
  }, [projectId]);

  async function loadData() {
    setLoading(true);
    const res = await functionService.list(projectId);
    setFns(res);
    setLoading(false);
  }

  function addParam() {
    setParams(prev => [...prev, { key: "", type: "string", description: "" }]);
  }
  function removeParam(i: number) {
    setParams(prev => prev.filter((_, idx) => idx !== i));
  }
  function updateParam(i: number, field: keyof Param, value: string) {
    setParams(prev => prev.map((p, idx) => idx === i ? { ...p, [field]: value } : p));
  }

  async function handleCreate() {
    const validName = name.trim().toLowerCase().replace(/\s+/g, "_");
    if (!validName || !description.trim()) return;
    setSaving(true);

    const validParams = params.filter(p => p.key.trim());
    const properties: FunctionParameter["properties"] = Object.fromEntries(
      validParams.map(p => [p.key, { type: p.type, description: p.description || undefined }])
    );

    const input: CreateFunctionInput = {
      projectId,
      name: validName,
      description: description.trim(),
      parameters: {
        type: "object",
        properties,
        required: validParams.map(p => p.key),
      },
      requiresAuth,
      requiresConfirmation,
    };
    await functionService.create(input);
    setIsAdding(false);
    setName(""); setDescription(""); setRequiresAuth(false); setRequiresConfirmation(false);
    setParams([{ key: "", type: "string", description: "" }]);
    loadData();
    setSaving(false);
  }

  async function handleDelete(id: string) {
    if (!confirm("Delete this function? The AI will no longer be able to call it.")) return;
    await functionService.delete(projectId, id);
    loadData();
  }

  function formatSchema(fn: ConsoleFunction): string {
    return JSON.stringify(fn.parameters, null, 2);
  }

  function getParamCount(fn: ConsoleFunction) {
    return Object.keys(fn.parameters?.properties || {}).length;
  }

  function toggleSort(field: "name" | "status") {
    if (sortField === field) setSortAsc(!sortAsc);
    else { setSortField(field); setSortAsc(true); }
    setCurrentPage(1);
  }

  // Filter & Sort Logic
  const filteredData = fns.filter(f => 
    f.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    f.description.toLowerCase().includes(searchQuery.toLowerCase())
  ).sort((a, b) => {
    let cmp = 0;
    if (sortField === "name") cmp = a.name.localeCompare(b.name);
    else cmp = a.status.localeCompare(b.status);
    return sortAsc ? cmp : -cmp;
  });

  // Paging Logic
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = filteredData.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  return (
    <div className="flex flex-col gap-6 w-full pb-10 h-full flex-1">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-text-primary mb-1">Functions / Tools</h1>
          <p className="text-text-secondary text-sm">Register native app capabilities as callable AI tools.</p>
        </div>
        <Button variant="primary" icon={<Plus className="w-4 h-4" />} onClick={() => setIsAdding(!isAdding)}>
          Add Function
        </Button>
      </div>

      {/* Basic Stats Banner instead of knowledge conflict */}
      <div className="bg-accent/10 border border-accent/20 rounded-xl p-4 flex gap-4">
        <div className="w-8 h-8 rounded-full bg-accent/20 flex items-center justify-center shrink-0"><Zap className="w-4 h-4 text-accent" /></div>
        <div className="text-sm">
          <h3 className="font-semibold text-accent mb-1">How Function Calling Works</h3>
          <p className="text-text-secondary leading-relaxed">
            Functions defined here are compiled into <strong>JSON Schema</strong> and injected into the LLM logic. 
            When triggered, the INFRIA SDK pauses generation and emits a <code className="bg-bg-elevated px-1 rounded">tool_call</code> event back to your mobile/web app.
          </p>
        </div>
      </div>

      {/* Add Function Form */}
      {isAdding && (
        <div className="bg-bg-surface border border-border-default rounded-xl p-6 space-y-6 shadow-sm">
          <div className="flex justify-between items-center">
            <h2 className="font-semibold text-text-primary">Define New Function</h2>
            <button onClick={() => setIsAdding(false)}><X className="w-4 h-4 text-text-muted hover:text-text-primary transition-colors" /></button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-text-secondary mb-1 uppercase tracking-wide">Function Name</label>
              <input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. cancel_order (snake_case)" className="w-full px-3 py-2 bg-bg-elevated border border-border-strong rounded-md text-text-primary focus:border-accent outline-none text-sm" />
              <p className="text-xs text-text-muted mt-1">Will be auto-converted to snake_case</p>
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-secondary mb-1 uppercase tracking-wide">Description</label>
              <input value={description} onChange={e => setDescription(e.target.value)} placeholder="Describe what this function does (AI uses this to decide when to call it)" className="w-full px-3 py-2 bg-bg-elevated border border-border-strong rounded-md text-text-primary focus:border-accent outline-none text-sm" />
              <p className="text-xs text-text-muted mt-1">Be specific ΓÇö the AI uses this to decide when to call</p>
            </div>
          </div>

          {/* Parameter Builder */}
          <div>
            <div className="flex justify-between items-center mb-3">
              <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Parameters</label>
              <button onClick={addParam} className="text-xs text-accent hover:underline flex items-center gap-1"><Plus className="w-3 h-3" /> Add Parameter</button>
            </div>
            {params.length === 0 ? (
              <p className="text-xs text-text-muted italic">No parameters ΓÇö this function takes no input from the AI.</p>
            ) : (
              <div className="space-y-3">
                <div className="grid grid-cols-12 gap-2 text-xs text-text-muted font-semibold uppercase tracking-wide px-1">
                  <span className="col-span-4">Key Name</span>
                  <span className="col-span-3">Type</span>
                  <span className="col-span-4">Description (optional)</span>
                  <span className="col-span-1"></span>
                </div>
                {params.map((p, i) => (
                  <div key={i} className="grid grid-cols-12 gap-2 items-center">
                    <input value={p.key} onChange={e => updateParam(i, "key", e.target.value)} placeholder="e.g. order_id" className="col-span-4 px-3 py-1.5 bg-bg-elevated border border-border-strong rounded-md text-sm font-mono text-text-primary focus:border-accent outline-none" />
                    <select value={p.type} onChange={e => updateParam(i, "type", e.target.value)} className="col-span-3 px-2 py-1.5 bg-bg-elevated border border-border-strong rounded-md text-sm text-text-primary focus:border-accent outline-none">
                      {TYPE_OPTIONS.map(t => <option key={t}>{t}</option>)}
                    </select>
                    <input value={p.description} onChange={e => updateParam(i, "description", e.target.value)} placeholder="What is this param?" className="col-span-4 px-3 py-1.5 bg-bg-elevated border border-border-strong rounded-md text-sm text-text-primary focus:border-accent outline-none" />
                    <button onClick={() => removeParam(i)} className="col-span-1 flex justify-center"><X className="w-3.5 h-3.5 text-text-muted hover:text-status-error" /></button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Options */}
          <div className="flex gap-6 pt-2 border-t border-border-subtle">
            <label className="flex items-center gap-2 text-sm text-text-secondary cursor-pointer hover:text-text-primary">
              <input type="checkbox" checked={requiresAuth} onChange={e => setRequiresAuth(e.target.checked)} className="w-4 h-4 rounded accent-accent" />
              Requires User Auth
            </label>
            <label className="flex items-center gap-2 text-sm text-text-secondary cursor-pointer hover:text-text-primary">
              <input type="checkbox" checked={requiresConfirmation} onChange={e => setRequiresConfirmation(e.target.checked)} className="w-4 h-4 rounded accent-accent" />
              Requires Confirmation Dialog
            </label>
          </div>

          <div className="flex justify-end gap-3 pt-2">
            <Button variant="ghost" onClick={() => setIsAdding(false)}>Cancel</Button>
            <Button variant="primary" onClick={handleCreate} disabled={saving || !name || !description}>
              {saving ? <><Loader2 className="w-4 h-4 animate-spin mr-1" /> Saving...</> : "Save Function"}
            </Button>
          </div>
        </div>
      )}

      {/* Table Section */}
      {loading ? (
        <div className="flex justify-center py-16"><Loader2 className="w-7 h-7 animate-spin text-accent" /></div>
      ) : fns.length === 0 ? (
        <EmptyState
          title="No functions registered"
          description="Add your first function to let the AI take actions in your app."
          icon={<Zap className="w-8 h-8" />}
        />
      ) : (
        <div className="bg-bg-surface border border-border-default rounded-xl overflow-hidden shadow-sm flex flex-col flex-1 min-h-[400px]">
          {/* Controls: Search */}
          <div className="border-b border-border-subtle bg-bg-elevated p-3 pl-4 flex gap-4">
             <div className="relative w-full sm:w-64">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-muted" />
               <input
                 value={searchQuery}
                 onChange={e => { setSearchQuery(e.target.value); setCurrentPage(1); }}
                 placeholder="Search functions..."
                 className="w-full pl-9 pr-3 py-2 bg-bg-base border border-border-strong rounded-md text-sm text-text-primary focus:border-accent outline-none"
               />
             </div>
             <div className="flex items-center text-text-muted text-xs font-semibold px-2">{filteredData.length} functions found</div>
          </div>

          <div className="flex-1 overflow-auto">
            <table className="w-full text-left text-sm whitespace-nowrap">
              <thead className="bg-bg-surface border-b border-border-default text-text-secondary sticky top-0 z-10">
                <tr>
                  <th className="px-6 py-3 font-medium cursor-pointer hover:bg-bg-hover transition-colors" onClick={() => toggleSort("name")}>
                     <div className="flex items-center gap-1">Function Name <ArrowUpDown className="w-3.5 h-3.5 text-text-muted opacity-50" /></div>
                  </th>
                  <th className="px-6 py-3 font-medium">Description</th>
                  <th className="px-6 py-3 font-medium">Params</th>
                  <th className="px-6 py-3 font-medium">Flags</th>
                  <th className="px-6 py-3 font-medium cursor-pointer hover:bg-bg-hover transition-colors" onClick={() => toggleSort("status")}>
                     <div className="flex items-center gap-1">Status <ArrowUpDown className="w-3.5 h-3.5 text-text-muted opacity-50" /></div>
                  </th>
                  <th className="px-6 py-3 font-medium text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border-subtle bg-bg-surface">
                {paginatedData.map(fn => (
                  <React.Fragment key={fn.id}>
                    <tr className="hover:bg-bg-hover cursor-pointer" onClick={() => setExpandedId(expandedId === fn.id ? null : fn.id)}>
                      <td className="px-6 py-4 font-mono text-sm font-semibold text-text-primary">{fn.name}</td>
                      <td className="px-6 py-4 text-text-secondary max-w-[200px]">
                        <p className="truncate block pr-4">{fn.description}</p>
                      </td>
                      <td className="px-6 py-4 text-text-secondary">
                        {getParamCount(fn) > 0 ? <span className="font-medium bg-bg-elevated px-2 py-1 rounded border border-border-default text-xs">{getParamCount(fn)} param{getParamCount(fn) > 1 ? "s" : ""}</span> : <span className="text-text-muted italic text-xs">none</span>}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex gap-1">
                          {fn.requiresAuth && <span className="text-xs bg-accent/10 text-accent border border-accent/20 px-1.5 py-0.5 rounded font-medium">auth</span>}
                          {fn.requiresConfirmation && <span className="text-xs bg-status-warning/10 text-status-warning border border-status-warning/20 px-1.5 py-0.5 rounded font-medium">confirm</span>}
                          {!fn.requiresAuth && !fn.requiresConfirmation && <span className="text-xs text-text-muted">ΓÇö</span>}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <Badge variant={fn.status === "active" ? "success" : "default"}>{fn.status}</Badge>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-end gap-3">
                          <button onClick={e => { e.stopPropagation(); handleDelete(fn.id); }} className="text-text-muted hover:text-status-error transition-colors p-1">
                            <Trash2 className="w-4 h-4" />
                          </button>
                          {expandedId === fn.id ? <ChevronUp className="w-5 h-5 text-text-muted" /> : <ChevronDown className="w-5 h-5 text-text-muted" />}
                        </div>
                      </td>
                    </tr>
                    {expandedId === fn.id && (
                      <tr key={`${fn.id}-exp`}>
                        <td colSpan={6} className="bg-bg-base px-6 py-5 border-b border-border-subtle shadow-inner">
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                              <p className="text-xs font-semibold text-text-secondary mb-2 uppercase tracking-wider flex items-center justify-between">
                                JSON Schema 
                                <span className="text-[10px] normal-case tracking-normal px-2 py-0.5 bg-bg-surface border border-border-strong rounded text-text-muted">Injected to LLM</span>
                              </p>
                              <pre className="font-mono text-xs bg-bg-elevated p-4 rounded-lg text-text-secondary overflow-x-auto border border-border-default shadow-sm">{formatSchema(fn)}</pre>
                            </div>
                            <div>
                              <p className="text-xs font-semibold text-text-secondary mb-2 uppercase tracking-wider flex items-center justify-between">
                                Flutter Implementation 
                                <span className="text-[10px] normal-case tracking-normal px-2 py-0.5 bg-bg-surface border border-border-strong rounded text-text-muted">Client Side Code</span>
                              </p>
                              <pre className="font-mono text-[11px] bg-[#1E1E1E] p-4 rounded-lg text-[#D4D4D4] overflow-x-auto border border-[#333333] shadow-sm leading-relaxed">{functionService.generateFlutterSnippet(fn)}</pre>
                            </div>
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
                {paginatedData.length === 0 && (
                  <tr><td colSpan={6} className="text-center py-10 text-text-muted text-sm border-t border-border-default">No functions match your search.</td></tr>
                )}
              </tbody>
            </table>
          </div>

          {/* Pagination Footer */}
          {totalPages > 1 && (
             <div className="border-t border-border-subtle bg-bg-elevated p-3 px-6 flex items-center justify-between text-sm">
                <span className="text-text-muted font-medium">Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, filteredData.length)} of {filteredData.length} functions</span>
                <div className="flex gap-2">
                   <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="px-4 py-1.5 rounded-md bg-bg-base border border-border-strong text-text-secondary disabled:opacity-50 hover:bg-bg-hover hover:text-text-primary transition-colors font-semibold shadow-sm">Prev</button>
                   <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="px-4 py-1.5 rounded-md bg-bg-base border border-border-strong text-text-secondary disabled:opacity-50 hover:bg-bg-hover hover:text-text-primary transition-colors font-semibold shadow-sm">Next</button>
                </div>
             </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { knowledgeService } from "@/services/knowledge.service";
import { Knowledge } from "@/types";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { EmptyState } from "@/components/ui/EmptyState";
import { FileText, Plus, RefreshCw, Trash2, ChevronDown, ChevronUp, Eye, Loader2, Search, Grid2X2, ArrowUpDown } from "lucide-react";

const CATEGORIES = ["Policy & FAQ", "Internal SOP", "Product Info", "Pricing", "Technical Docs", "Other", "Custom..."];

type KnowledgeStatus = "draft" | "processing" | "ready" | "failed" | "archived";

function StatusBadge({ status }: { status: KnowledgeStatus }) {
  const map: Record<KnowledgeStatus, "success" | "default" | "info" | "error" | "warning"> = {
    ready: "success",
    processing: "info",
    draft: "default",
    failed: "error",
    archived: "warning",
  };
  return <Badge variant={map[status] || "default"}>{status}</Badge>;
}

export default function KnowledgePage() {
  const { projectId } = useParams<{ projectId: string }>();
  const [data, setData] = useState<Knowledge[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  
  // Table Controls
  const [searchQuery, setSearchQuery] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("All");
  const [sortField, setSortField] = useState<"createdAt" | "title">("createdAt");
  const [sortAsc, setSortAsc] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;

  const [viewMode, setViewMode] = useState<"text" | "chunks">("text");

  // Form State
  const [isAdding, setIsAdding] = useState(false);
  const [saving, setSaving] = useState(false);
  const [title, setTitle] = useState("");
  const [category, setCategory] = useState(CATEGORIES[0]);
  const [customCategory, setCustomCategory] = useState("");
  const [content, setContent] = useState("");

  const estimatedChunks = Math.ceil(content.length / 800); // More realistic chunk logic ~800 chars

  useEffect(() => { loadData(); }, [projectId]);

  async function loadData() {
    setLoading(true);
    const res = await knowledgeService.list(projectId);
    setData(res);
    setLoading(false);
  }

  async function handleAdd() {
    if (!title.trim() || !content.trim()) return;
    
    const finalCategory = category === "Custom..." ? customCategory.trim() : category;
    if (!finalCategory) return;

    setSaving(true);
    const drafted = await knowledgeService.createDraft({ projectId, title, category: finalCategory, content });
    await knowledgeService.publish(projectId, drafted.id);
    setIsAdding(false);
    setTitle(""); setCategory(CATEGORIES[0]); setCustomCategory(""); setContent("");
    setSaving(false);
    loadData();
  }

  async function handleDelete(id: string) {
    if (!confirm("Delete this knowledge entry?")) return;
    await knowledgeService.delete(projectId, id);
    loadData();
  }

  async function handleReindex(id: string) {
    await knowledgeService.reindex(projectId, id);
    loadData();
  }

  // Filtering & Sorting Logic
  const filteredData = data.filter(d => {
     const matchesSearch = d.title.toLowerCase().includes(searchQuery.toLowerCase()) || d.content.toLowerCase().includes(searchQuery.toLowerCase());
     const matchesCategory = categoryFilter === "All" || d.category === categoryFilter;
     return matchesSearch && matchesCategory;
  }).sort((a, b) => {
     let cmp = 0;
     if (sortField === "title") cmp = a.title.localeCompare(b.title);
     else cmp = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
     return sortAsc ? cmp : -cmp;
  });

  // Paging Logic
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = filteredData.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const categoryGroups = Array.from(new Set(data.map(d => d.category)));

  // Dummy Smart Chunking Simulator for Client-side preview (Approx ~500 chars/chunk)
  function renderChunksPreview(contentString: string) {
    if (!contentString) return null;
    const chunkSize = 500;
    const chunks = [];
    for (let i = 0; i < contentString.length; i += chunkSize) {
        chunks.push(contentString.slice(i, i + chunkSize));
    }
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
        {chunks.map((chunk, idx) => (
          <div key={idx} className="bg-bg-elevated border border-border-default rounded-xl p-4 flex flex-col">
             <div className="flex items-center justify-between mb-2">
               <span className="text-xs font-semibold text-text-muted">Chunk {idx + 1}</span>
               <span className="text-[10px] bg-bg-surface px-1.5 py-0.5 rounded border border-border-subtle text-text-secondary">{chunk.length} chars</span>
             </div>
             <p className="text-xs text-text-primary leading-relaxed flex-1 line-clamp-6">{chunk}{chunk.length === chunkSize ? '...' : ''}</p>
          </div>
        ))}
      </div>
    );
  }

  function toggleSort(field: "createdAt" | "title") {
     if (sortField === field) setSortAsc(!sortAsc);
     else { setSortField(field); setSortAsc(true); }
     setCurrentPage(1);
  }

  return (
    <div className="flex flex-col gap-6 w-full pb-10 h-full">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-text-primary mb-1">Knowledge Base</h1>
          <p className="text-text-secondary text-sm">Documents used for Retrieval-Augmented Generation (RAG) context injection.</p>
        </div>
        <Button variant="primary" icon={<Plus className="w-4 h-4" />} onClick={() => setIsAdding(!isAdding)}>
          Add Knowledge
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {[
          { label: "Total Documents", value: data.length },
          { label: "Ready for RAG", value: data.filter(d => d.status === "ready").length },
          { label: "Total Chunks", value: data.reduce((s, d) => s + (d.chunkCount || 0), 0) },
        ].map(stat => (
          <div key={stat.label} className="bg-bg-surface border border-border-default rounded-xl p-4">
            <p className="text-2xl font-bold text-text-primary">{stat.value}</p>
            <p className="text-xs text-text-secondary mt-1">{stat.label}</p>
          </div>
        ))}
      </div>
      
      {/* Test Retrieval omitted for brevity, keeping UI clean for Phase 7 */}

      {/* Add Form */}
      {isAdding && (
        <div className="bg-bg-surface border border-border-default rounded-xl p-6 space-y-4">
          <h2 className="text-base font-semibold text-text-primary">Add New Knowledge Entry</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-text-secondary mb-1">Title</label>
              <input value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. Return Policy 2026" className="w-full px-3 py-2 bg-bg-elevated border border-border-strong rounded-md text-text-primary focus:border-accent outline-none text-sm" />
            </div>
            <div>
              <label className="block text-sm font-medium text-text-secondary mb-1">Category</label>
              <div className="flex gap-2">
                <select value={category} onChange={e => setCategory(e.target.value)} className={`${category === 'Custom...' ? 'w-1/2' : 'w-full'} px-3 py-2 bg-bg-elevated border border-border-strong rounded-md text-text-primary focus:border-accent outline-none text-sm`}>
                  {CATEGORIES.map(c => <option key={c}>{c}</option>)}
                </select>
                {category === 'Custom...' && (
                  <input autoFocus value={customCategory} onChange={e => setCustomCategory(e.target.value)} placeholder="Custom category..." className="flex-1 px-3 py-2 bg-bg-elevated border border-border-strong rounded-md text-text-primary focus:border-accent outline-none text-sm" />
                )}
              </div>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-text-secondary mb-1">Content</label>
            <p className="text-xs text-text-muted mb-2">Paste the full document text. INFRIA will automatically chunk and vectorize it.</p>
            <textarea
              value={content}
              onChange={e => setContent(e.target.value)}
              rows={8}
              placeholder="Paste document content here. The more detailed, the better the AI's answers will be..."
              className="w-full px-3 py-2 bg-bg-elevated border border-border-strong rounded-md text-text-primary focus:border-accent outline-none resize-none text-sm font-mono"
            />
            <div className="flex items-center justify-between mt-1">
              <p className="text-xs text-text-muted">{content.length} characters</p>
              <Badge variant="info">~{content ? estimatedChunks : 0} chunks estimated</Badge>
            </div>
          </div>
          <div className="flex justify-end gap-3 pt-2 border-t border-border-subtle">
            <Button variant="ghost" onClick={() => setIsAdding(false)}>Cancel</Button>
            <Button variant="primary" onClick={handleAdd} disabled={saving || !title || !content || (category === "Custom..." && !customCategory)}>
              {saving ? <><Loader2 className="w-4 h-4 animate-spin mr-1" /> Processing...</> : "Save & Vectorize"}
            </Button>
          </div>
        </div>
      )}

      {/* Table Section */}
      {loading ? (
        <div className="flex justify-center py-20"><Loader2 className="w-7 h-7 animate-spin text-accent" /></div>
      ) : data.length === 0 ? (
        <EmptyState
          title="No knowledge entries"
          description="Start adding documents. The AI will use them to answer user questions."
          icon={<FileText className="w-8 h-8" />}
        />
      ) : (
        <div className="bg-bg-surface border border-border-default rounded-xl overflow-hidden shadow-sm flex flex-col flex-1 min-h-[400px]">
          {/* Controls: Search + Categories */}
          <div className="border-b border-border-subtle bg-bg-elevated p-3 pl-4 flex flex-col sm:flex-row sm:items-center gap-4">
             <div className="relative w-full sm:w-64 shrink-0">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-muted" />
               <input
                 value={searchQuery}
                 onChange={e => { setSearchQuery(e.target.value); setCurrentPage(1); }}
                 placeholder="Search documents..."
                 className="w-full pl-9 pr-3 py-2 bg-bg-base border border-border-strong rounded-md text-sm text-text-primary focus:border-accent outline-none"
               />
             </div>
             
             {/* Slideable Category Filters */}
             <div className="flex-1 min-w-0 overflow-x-auto no-scrollbar mask-edges-right flex gap-1 items-center -mb-2 pb-2 sm:mb-0 sm:pb-0">
               <button onClick={() => { setCategoryFilter("All"); setCurrentPage(1); }} className={`px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition-colors ${categoryFilter === "All" ? "bg-text-primary text-bg-base" : "bg-bg-surface border border-border-strong text-text-secondary hover:bg-bg-hover"}`}>
                  All ({data.length})
               </button>
               {categoryGroups.map(cat => (
                 <button key={cat} onClick={() => { setCategoryFilter(cat); setCurrentPage(1); }} className={`px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition-colors ${categoryFilter === cat ? "bg-text-primary text-bg-base" : "bg-bg-surface border border-border-strong text-text-secondary hover:bg-bg-hover"}`}>
                   {cat}
                 </button>
               ))}
             </div>
          </div>

          {/* Table */}
          <div className="flex-1 overflow-auto">
            <table className="w-full text-left text-sm whitespace-nowrap">
              <thead className="bg-bg-surface border-b border-border-default text-text-secondary sticky top-0 z-10">
                <tr>
                  <th className="px-6 py-3 font-medium cursor-pointer hover:bg-bg-hover transition-colors" onClick={() => toggleSort("title")}>
                     <div className="flex items-center gap-1">Title <ArrowUpDown className="w-3.5 h-3.5 text-text-muted opacity-50" /></div>
                  </th>
                  <th className="px-6 py-3 font-medium">Category</th>
                  <th className="px-6 py-3 font-medium">Chunks</th>
                  <th className="px-6 py-3 font-medium">Status</th>
                  <th className="px-6 py-3 font-medium cursor-pointer hover:bg-bg-hover transition-colors" onClick={() => toggleSort("createdAt")}>
                     <div className="flex items-center gap-1">Added <ArrowUpDown className="w-3.5 h-3.5 text-text-muted opacity-50" /></div>
                  </th>
                  <th className="px-6 py-3 font-medium text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border-subtle bg-bg-surface">
                {paginatedData.map(item => (
                  <React.Fragment key={item.id}>
                    <tr
                      className="hover:bg-bg-hover cursor-pointer"
                      onClick={() => setExpandedId(expandedId === item.id ? null : item.id)}
                    >
                      <td className="px-6 py-4 whitespace-normal break-words min-w-[200px] lg:max-w-md xl:max-w-lg">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-accent/10 border border-accent/20 flex flex-shrink-0 items-center justify-center">
                             <FileText className="w-4 h-4 text-accent" />
                          </div>
                          <span className="font-semibold text-text-primary">{item.title}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-xs px-2.5 py-1 bg-bg-elevated border border-border-default rounded-md text-text-secondary font-medium tracking-wide">{item.category}</span>
                      </td>
                      <td className="px-6 py-4 text-text-secondary">{item.chunkCount > 0 ? `${item.chunkCount} chunks` : "ΓÇö"}</td>
                      <td className="px-6 py-4"><StatusBadge status={item.status as KnowledgeStatus} /></td>
                      <td className="px-6 py-4 text-text-muted text-xs font-medium">{new Date(item.createdAt).toLocaleDateString()}</td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-end gap-3">
                          <button title="Reindex" onClick={e => { e.stopPropagation(); handleReindex(item.id); }} className="text-text-muted hover:text-accent transition-colors">
                            <RefreshCw className="w-4 h-4" />
                          </button>
                          <button title="Delete" onClick={e => { e.stopPropagation(); handleDelete(item.id); }} className="text-text-muted hover:text-status-error transition-colors">
                            <Trash2 className="w-4 h-4" />
                          </button>
                          {expandedId === item.id ? <ChevronUp className="w-5 h-5 text-text-muted" /> : <ChevronDown className="w-5 h-5 text-text-muted" />}
                        </div>
                      </td>
                    </tr>
                    {expandedId === item.id && (
                      <tr key={`${item.id}-exp`}>
                        <td colSpan={6} className="bg-bg-base px-6 py-5 border-b border-border-subtle shadow-inner">
                          <div className="flex items-center justify-between mb-4">
                             <div className="flex gap-4 text-xs text-text-secondary">
                               <div><span className="font-semibold text-text-primary block mb-0.5">Vector Info</span>{item.chunkCount > 0 ? `${item.chunkCount} chunks ready` : "Not yet vectorized"}</div>
                             </div>
                             <div className="flex bg-bg-surface border border-border-strong rounded-md p-1 gap-1">
                               <button onClick={() => setViewMode("text")} className={`px-3 py-1 flex items-center gap-1.5 text-xs font-medium rounded ${viewMode === 'text' ? 'bg-accent text-white' : 'text-text-secondary hover:bg-bg-elevated'}`}><Eye className="w-3.5 h-3.5" /> Full Text</button>
                               <button onClick={() => setViewMode("chunks")} className={`px-3 py-1 flex items-center gap-1.5 text-xs font-medium rounded ${viewMode === 'chunks' ? 'bg-accent text-white' : 'text-text-secondary hover:bg-bg-elevated'}`}><Grid2X2 className="w-3.5 h-3.5" /> Preview Dummy Chunks</button>
                             </div>
                          </div>
                          
                          {viewMode === "text" ? (
                            <div>
                              <div className="bg-bg-elevated border border-border-default rounded-lg p-4 max-h-60 overflow-y-auto w-full">
                                <pre className="text-xs text-text-secondary leading-relaxed whitespace-pre-wrap font-sans">{item.content || "(No content stored)"}</pre>
                              </div>
                            </div>
                          ) : (
                            <div className="bg-bg-surface p-1 rounded-lg border border-border-default max-h-[300px] overflow-y-auto p-4 shadow-inner">
                              <div className="mb-4 bg-status-info/10 text-status-info border border-status-info/20 px-3 py-2 rounded-md text-xs font-medium inline-block">
                                 Note: This is a client-side mockup of text splitting. Actual embeddings are processed by the INFRIA backend RAG pipeline.
                              </div>
                              {renderChunksPreview(item.content)}
                            </div>
                          )}
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
                {paginatedData.length === 0 && (
                  <tr><td colSpan={6} className="text-center py-10 text-text-muted text-sm border-t border-border-default">No results found in this category.</td></tr>
                )}
              </tbody>
            </table>
          </div>
          
          {/* Pagination Footer */}
          {totalPages > 1 && (
             <div className="border-t border-border-subtle bg-bg-elevated p-3 px-6 flex items-center justify-between text-sm">
                <span className="text-text-muted">Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, filteredData.length)} of {filteredData.length} records</span>
                <div className="flex gap-1">
                   <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="px-3 py-1.5 rounded bg-bg-base border border-border-strong text-text-secondary disabled:opacity-50 hover:bg-bg-hover hover:text-text-primary transition-colors font-medium">Prev</button>
                   <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="px-3 py-1.5 rounded bg-bg-base border border-border-strong text-text-secondary disabled:opacity-50 hover:bg-bg-hover hover:text-text-primary transition-colors font-medium">Next</button>
                </div>
             </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
