"use client";

import React, { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { apiKeyService } from "@/services/apiKey.service";
import { projectService } from "@/services/project.service";
import { APIKey, Project } from "@/types";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { EmptyState } from "@/components/ui/EmptyState";
import { Key, Plus, Trash2, Copy, CheckCircle2, Eye, EyeOff, Loader2, Search, ArrowUpDown } from "lucide-react";
import { CodeBlock } from "@/components/ui/CodeBlock";

export default function AppSettingsPage() {
  const { projectId } = useParams<{ projectId: string }>();
  
  const [project, setProject] = useState<Project | null>(null);
  const [keys, setKeys] = useState<APIKey[]>([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState("");
  
  // Table Controls
  const [searchQuery, setSearchQuery] = useState("");
  const [sortField, setSortField] = useState<"name" | "createdAt">("createdAt");
  const [sortAsc, setSortAsc] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;

  // View state
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [newlyGeneratedKey, setNewlyGeneratedKey] = useState<string | null>(null);

  // Load apps from localStorage (sync logic with Overview)
  const [registeredApps, setRegisteredApps] = useState<{ id: string, name: string, platform: string, packageInfo?: string }[]>([]);

  useEffect(() => {
    projectService.list().then(res => setProject(res.find(p => p.id === projectId) || null));
    loadKeys();
    
    // Load registered apps
    try {
      const saved = localStorage.getItem(`infria_apps_${projectId}`);
      if (saved) setRegisteredApps(JSON.parse(saved));
    } catch(e) {}
  }, [projectId]);

  function handleRemoveApp(id: string) {
    if (!confirm("Are you sure you want to disconnect this app? SDK calls using this App Name might fail.")) return;
    const newApps = registeredApps.filter(a => a.id !== id);
    setRegisteredApps(newApps);
    localStorage.setItem(`infria_apps_${projectId}`, JSON.stringify(newApps));
  }

  async function loadKeys() {
    setLoading(true);
    const res = await apiKeyService.list(projectId);
    setKeys(res);
    setLoading(false);
  }

  async function handleCreate() {
    if (!newName) return;
    setCreating(true);
    const { rawKey } = await apiKeyService.generate(projectId, newName);
    setNewName("");
    setCreating(false);
    setNewlyGeneratedKey(rawKey);
    loadKeys();
  }

  async function revokeKey(id: string) {
    if (!confirm("Revoke this key? It will instantly stop working.")) return;
    await apiKeyService.revoke(projectId, id);
    loadKeys();
  }

  function handleCopy(key: string, id: string) {
    navigator.clipboard.writeText(key);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  }

  // Filter & Sort Logic
  const filteredData = keys.filter(k => 
    k.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    k.prefix.toLowerCase().includes(searchQuery.toLowerCase())
  ).sort((a, b) => {
    let cmp = 0;
    if (sortField === "name") cmp = a.name.localeCompare(b.name);
    else cmp = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
    return sortAsc ? cmp : -cmp;
  });

  // Paging Logic
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = filteredData.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  function toggleSort(field: "name" | "createdAt") {
    if (sortField === field) setSortAsc(!sortAsc);
    else { setSortField(field); setSortAsc(true); }
    setCurrentPage(1);
  }


  if (!project) return null;

  return (
    <div className="flex flex-col gap-6 w-full pb-10 h-full max-w-5xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-text-primary mb-1">App Settings & API Keys</h1>
          <p className="text-text-secondary text-sm">Manage client apps and secure backend API tokens.</p>
        </div>
      </div>

      <div className="flex gap-4 border-b border-border-default">
         <button className="px-4 py-2 border-b-2 border-accent text-accent font-semibold text-sm">General Settings</button>
      </div>

      <div className="flex flex-col gap-4">
         <div className="flex flex-col gap-1">
            <h2 className="text-lg font-bold text-text-primary">Connected Apps</h2>
            <p className="text-xs text-text-secondary leading-relaxed">Applications that have been initialized to run the INFRIA SDK logic. Go to Project Overview to add new ones.</p>
         </div>
         
         <div className="w-full">
            <div className="bg-bg-surface border border-border-default rounded-xl overflow-hidden shadow-sm">
               {registeredApps.length === 0 ? (
                 <div className="p-8 text-center text-sm text-text-muted">No apps connected yet. Please register one in the Dashboard.</div>
               ) : (
                 <div className="divide-y divide-border-subtle">
                   {registeredApps.map(app => (
                     <div key={app.id} className="p-5 hover:bg-bg-elevated transition-colors">
                        <div className="flex items-center justify-between mb-3">
                           <div>
                             <h4 className="font-bold text-text-primary text-base">{app.name}</h4>
                             <p className="text-xs text-text-muted mt-0.5 font-mono">{app.packageInfo || "No Package ID set"}</p>
                           </div>
                           <div className="flex items-center gap-3">
                              <Badge variant="info" className="uppercase tracking-wider">{app.platform}</Badge>
                              <button onClick={() => handleRemoveApp(app.id)} className="text-text-muted hover:text-status-error transition-colors p-1" title="Disconnect App">
                                 <Trash2 className="w-4 h-4" />
                              </button>
                           </div>
                        </div>
                        {/* Config Code block depending on platform for mockup */}
                        <div className="mt-4 bg-bg-base border border-border-strong rounded-lg p-3">
                           <div className="text-[10px] font-bold uppercase tracking-widest text-text-muted mb-2">Init Configuration</div>
                           <CodeBlock 
                             language={app.platform === 'flutter' ? 'dart' : app.platform === 'web' ? 'javascript' : 'swift'}
                             code={
app.platform === 'flutter' ? 
`import 'package:infria/infria.dart';

void main() async {
  await Infria.initializeApp(
     projectId: '${projectId}',
     appName: '${app.name}'
  );
}` : app.platform === 'web' ? 
`import { initializeApp } from 'infria/app';

const app = initializeApp({
  projectId: '${projectId}',
  appName: '${app.name}'
});` : `// Initialize matching ${app.platform} client with standard options\nInfriaApp.configure("${projectId}");`
                             } 
                           />
                        </div>
                     </div>
                   ))}
                 </div>
               )}
            </div>
         </div>
      </div>
      
      <div className="border-b border-border-subtle my-2" />

      {/* Secrets & API Keys API Section aligned to new standards */}
      <div className="flex flex-col gap-4">
         <div className="flex flex-col gap-1">
            <h2 className="text-lg font-bold text-text-primary">Backend API Keys</h2>
            <p className="text-xs text-text-secondary leading-relaxed">Use these secret keys to securely access INFRIA services directly from your own backend (Node.js, Go, Python, etc) without going through the Client SDKs.</p>
         </div>
         
         <div className="w-full">
           <div className="bg-bg-surface border border-border-default rounded-xl overflow-hidden shadow-sm flex flex-col">
              
              {/* Toolbar */}
              <div className="border-b border-border-subtle p-4 flex flex-col sm:flex-row sm:items-center gap-4 bg-bg-elevated">
                 <div className="relative flex-1">
                   <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-muted" />
                   <input
                     value={searchQuery}
                     onChange={e => { setSearchQuery(e.target.value); setCurrentPage(1); }}
                     placeholder="Search API keys..."
                     className="w-full pl-9 pr-3 py-2 bg-bg-base border border-border-strong rounded-md text-sm text-text-primary focus:border-accent outline-none"
                   />
                 </div>
                 <div className="flex items-center gap-2">
                   <input
                     value={newName}
                     onChange={e => setNewName(e.target.value)}
                     placeholder="New Key Name (e.g. Prod Server)"
                     className="w-[180px] px-3 py-2 bg-bg-base border border-border-strong rounded-md text-sm text-text-primary focus:border-accent outline-none"
                   />
                   <Button variant="primary" onClick={handleCreate} disabled={!newName || creating}>
                     {creating ? <Loader2 className="w-4 h-4 animate-spin" /> : "Generate"}
                   </Button>
                 </div>
              </div>

              {/* Table */}
              <div className="overflow-auto">
                 <table className="w-full text-left text-sm whitespace-nowrap">
                   <thead className="bg-bg-surface border-b border-border-default text-text-secondary sticky top-0 z-10">
                     <tr>
                       <th className="px-6 py-3 font-medium cursor-pointer hover:bg-bg-hover transition-colors" onClick={() => toggleSort("name")}>
                         <div className="flex items-center gap-1">Key Name <ArrowUpDown className="w-3.5 h-3.5 text-text-muted opacity-50" /></div>
                       </th>
                       <th className="px-6 py-3 font-medium">Key Prefix</th>
                       <th className="px-6 py-3 font-medium">Status</th>
                       <th className="px-6 py-3 font-medium cursor-pointer hover:bg-bg-hover transition-colors" onClick={() => toggleSort("createdAt")}>
                         <div className="flex items-center gap-1">Created <ArrowUpDown className="w-3.5 h-3.5 text-text-muted opacity-50" /></div>
                       </th>
                       <th className="px-6 py-3 font-medium text-right">Actions</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-border-subtle bg-bg-surface">
                     {loading ? (
                       <tr><td colSpan={5} className="py-10 text-center"><Loader2 className="w-6 h-6 animate-spin text-accent mx-auto" /></td></tr>
                     ) : paginatedData.length === 0 ? (
                       <tr><td colSpan={5} className="py-10 text-center text-text-muted"><EmptyState title="No Keys" description="No keys found." icon={<Key className="w-6 h-6"/>} /></td></tr>
                     ) : (
                       paginatedData.map(key => (
                         <tr key={key.id} className="hover:bg-bg-hover transition-colors">
                           <td className="px-6 py-4 font-semibold text-text-primary whitespace-normal break-words min-w-[200px] lg:max-w-md">{key.name}</td>
                           <td className="px-6 py-4 font-mono text-xs max-w-[200px] truncate">
                              <span className="flex items-center gap-2 bg-bg-elevated px-2 py-1 rounded inline-flex border border-border-strong">
                                {key.prefix}
                              </span>
                           </td>
                           <td className="px-6 py-4">
                             <Badge variant={key.status === "active" ? "success" : "error"}>{key.status}</Badge>
                           </td>
                           <td className="px-6 py-4 text-xs text-text-muted">{new Date(key.createdAt).toLocaleDateString()}</td>
                           <td className="px-6 py-4">
                             <div className="flex items-center justify-end gap-3">
                               {key.status === "active" && (
                                 <button
                                   onClick={() => revokeKey(key.id)}
                                   className="text-text-muted hover:text-status-error transition-colors"
                                   title="Revoke Key"
                                 >
                                   <Trash2 className="w-4 h-4" />
                                 </button>
                               )}
                             </div>
                           </td>
                         </tr>
                       ))
                     )}
                   </tbody>
                 </table>
              </div>
              
              {/* Pagination */}
              {!loading && totalPages > 1 && (
                 <div className="border-t border-border-subtle bg-bg-elevated p-3 px-6 flex items-center justify-between text-sm">
                    <span className="text-text-muted font-medium">Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, filteredData.length)} of {filteredData.length} keys</span>
                    <div className="flex gap-2">
                       <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="px-4 py-1.5 rounded-md bg-bg-base border border-border-strong text-text-secondary disabled:opacity-50 hover:bg-bg-hover hover:text-text-primary transition-colors font-semibold shadow-sm">Prev</button>
                       <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="px-4 py-1.5 rounded-md bg-bg-base border border-border-strong text-text-secondary disabled:opacity-50 hover:bg-bg-hover hover:text-text-primary transition-colors font-semibold shadow-sm">Next</button>
                    </div>
                 </div>
              )}
           </div>
         </div>
      </div>

      {newlyGeneratedKey && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
          <div className="bg-bg-surface border border-border-default rounded-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-200 shadow-2xl p-8">
            <h2 className="text-xl font-bold text-text-primary mb-2 flex items-center gap-2">
              <Key className="w-5 h-5 text-accent" />
              API Key Generated
            </h2>
            <p className="text-sm text-text-secondary mb-6 leading-relaxed">
              Please copy this key and store it securely. For your security, <strong className="text-text-primary font-bold">it will not be shown again</strong>.
            </p>
            <div className="relative mb-6">
              <input readOnly value={newlyGeneratedKey} className="w-full pl-3 pr-12 py-3 bg-bg-elevated border border-border-strong rounded-lg text-text-primary font-mono text-sm outline-none shadow-inner" />
              <button 
                onClick={() => {
                  navigator.clipboard.writeText(newlyGeneratedKey);
                  setCopiedId('modal');
                  setTimeout(() => setCopiedId(null), 2000);
                }}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-md hover:bg-bg-hover text-text-secondary hover:text-text-primary transition-colors"
                title="Copy full access key"
              >
                {copiedId === 'modal' ? <CheckCircle2 className="w-4 h-4 text-status-success" /> : <Copy className="w-4 h-4" />}
              </button>
            </div>
            <Button variant="primary" className="w-full py-2.5" onClick={() => setNewlyGeneratedKey(null)}>
              I've copied it securely
            </Button>
          </div>
        </div>
      )}

    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { Send, Smartphone, TerminalSquare, AlertTriangle, Code2, Database, Zap } from "lucide-react";

type Message = {
  id: string;
  role: "user" | "assistant";
  content: string;
};

type TraceLog = {
  id: string;
  type: "system" | "rag" | "function" | "llm" | "error";
  message: string;
  timestamp: string;
};

export default function SimulatorPage() {
  const [messages, setMessages] = useState<Message[]>([
    { id: "1", role: "assistant", content: "Halo! Saya INFRIA Assistant. Ada yang bisa saya bantu terkait aplikasi ini?" }
  ]);
  const [inputMsg, setInputMsg] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [logs, setLogs] = useState<TraceLog[]>([]);
  const logsEndRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Auto scroll logs
  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [logs]);

  // Auto scroll chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isTyping]);

  const addLog = (type: TraceLog["type"], message: string) => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      type,
      message,
      timestamp: new Date().toISOString().substring(11, 23)
    }]);
  };

  const handleSend = async () => {
    if (!inputMsg.trim()) return;
    const userMsg = inputMsg.trim();
    setInputMsg("");

    // 1. Add user message
    setMessages(prev => [...prev, { id: Math.random().toString(), role: "user", content: userMsg }]);
    
    // 2. Start Processing Simulation
    setIsTyping(true);
    addLog("system", `[ROUTER] Received incoming message: "${userMsg}"`);
    
    // Fake processing delay
    await new Promise(r => setTimeout(r, 600));

    const lowercaseMsg = userMsg.toLowerCase();
    
    if (lowercaseMsg.includes("pesanan") || lowercaseMsg.includes("batal")) {
      // Simulate Function Call scenario
      addLog("system", "[ROUTER] Intent identified: ACTION_REQUIRED");
      await new Promise(r => setTimeout(r, 500));
      addLog("function", "[FUNCTION_CALL] Determining suitable tools... Found: 'cancel_order'");
      await new Promise(r => setTimeout(r, 800));
      addLog("system", '[EXECUTION] Pausing LLM stream. dispatching callback to Flutter SDK: cancel_order({"order_id": "auto-filled"})');
      await new Promise(r => setTimeout(r, 1200));
      addLog("function", "[SDK_RESPONSE] Received callback from client: { status: 'CANCELLED_SUCCESS' }");
      await new Promise(r => setTimeout(r, 600));
      addLog("llm", "[LLM] Generating natural response based on SDK callback context...");
      
      setIsTyping(false);
      setMessages(prev => [...prev, { 
        id: Math.random().toString(), 
        role: "assistant", 
        content: "Baik, pesanan Anda telah berhasil dibatalkan sesuai instruksi dari sistem kami. Ada hal lain yang bisa dibantu?" 
      }]);

    } else if (lowercaseMsg.includes("refund") || lowercaseMsg.includes("syarat") || lowercaseMsg.includes("kebijakan")) {
      // Simulate RAG scenario
      addLog("system", "[ROUTER] Intent identified: KNOWLEDGE_RETRIEVAL");
      await new Promise(r => setTimeout(r, 600));
      addLog("rag", "[VECTOR_DB] Querying chunks with similarity threshold > 0.75...");
      await new Promise(r => setTimeout(r, 800));
      addLog("rag", "[RETRIEVED] Found 3 chunks from document: 'Kebijakan Pengembalian Dana 2026'");
      await new Promise(r => setTimeout(r, 800));
      addLog("llm", "[LLM] Augmenting prompt with retrieved chunks. Generating response...");
      
      setIsTyping(false);
      setMessages(prev => [...prev, { 
        id: Math.random().toString(), 
        role: "assistant", 
        content: "Menurut kebijakan kami, proses pengembalian dana (refund) dapat diajukan maksimal 7 hari setelah barang diterima, dengan syarat tag masih utuh. Apakah Anda ingin mengajukan refund sekarang?" 
      }]);

    } else {
      // Simulate General Chit Chat
      addLog("system", "[ROUTER] Intent identified: GENERAL_CONVERSATION");
      await new Promise(r => setTimeout(r, 500));
      addLog("llm", "[LLM] Generating response direct from base model...");
      
      setIsTyping(false);
      setMessages(prev => [...prev, { 
        id: Math.random().toString(), 
        role: "assistant", 
        content: "Mohon maaf, saya adalah asisten toko Anda. Saya bisa membantu mengecek pesanan, membatalkan transaksi, atau menjelaskan peraturan toko. Silakan tanyakan hal tersebut ya." 
      }]);
    }
  };

  const getLogStyle = (type: TraceLog["type"]) => {
    switch (type) {
      case "system": return "text-text-muted";
      case "rag": return "text-yellow-400";
      case "function": return "text-emerald-400";
      case "llm": return "text-blue-400";
      case "error": return "text-red-400";
      default: return "text-text-primary";
    }
  };

  const getLogIcon = (type: TraceLog["type"]) => {
    switch (type) {
      case "system": return <TerminalSquare className="w-3 h-3 mt-0.5 shrink-0" />;
      case "rag": return <Database className="w-3 h-3 mt-0.5 shrink-0" />;
      case "function": return <Code2 className="w-3 h-3 mt-0.5 shrink-0" />;
      case "error": return <AlertTriangle className="w-3 h-3 mt-0.5 shrink-0" />;
      case "llm": return <Zap className="w-3 h-3 mt-0.5 shrink-0" />;
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-56px)] w-full">
      <div className="px-6 py-4 flex items-center justify-between border-b border-border-default shrink-0">
        <div>
          <h1 className="text-xl font-bold text-text-primary mb-1">Simulator & Trace Debugger</h1>
          <p className="text-text-secondary text-sm">Test your RAG and Function Calling logic in real-time.</p>
        </div>
        <button onClick={() => { setMessages([{ id: "1", role: "assistant", content: "Halo! Saya INFRIA Assistant. Ada yang bisa saya bantu terkait aplikasi ini?" }]); setLogs([]); }} className="text-sm font-medium text-accent hover:underline">
          Reset Session
        </button>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Left Panel: Simulator Chat */}
        <div className="w-full lg:w-[450px] xl:w-[500px] border-r border-border-default bg-bg-surface flex flex-col shrink-0">
          <div className="bg-bg-elevated border-b border-border-default p-4 flex items-center justify-between">
             <div className="flex items-center gap-3">
               <div className="w-8 h-8 rounded bg-accent-muted flex items-center justify-center font-bold text-accent text-sm border border-accent-border">AI</div>
               <div>
                 <h2 className="font-bold text-sm text-text-primary">INFRIA Assistant</h2>
                 <p className="text-xs text-text-muted flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-status-success"></span> Runtime Active</p>
               </div>
             </div>
          </div>
          
          <div className="flex-1 overflow-y-auto p-6 flex flex-col gap-4 bg-bg-base">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}>
                <div className={`max-w-[85%] rounded-lg px-4 py-3 text-sm leading-relaxed shadow-sm border ${msg.role === "user" ? "bg-accent text-white border-accent" : "bg-bg-surface text-text-primary border-border-strong"}`}>
                  {msg.content}
                </div>
              </div>
            ))}
            
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-bg-surface border border-border-strong rounded-lg px-4 py-3 shadow-sm flex gap-1.5 items-center">
                  <span className="w-2 h-2 bg-text-muted rounded-full animate-bounce" style={{ animationDelay: "0ms" }}></span>
                  <span className="w-2 h-2 bg-text-muted rounded-full animate-bounce" style={{ animationDelay: "150ms" }}></span>
                  <span className="w-2 h-2 bg-text-muted rounded-full animate-bounce" style={{ animationDelay: "300ms" }}></span>
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          <div className="bg-bg-surface border-t border-border-default p-4 flex gap-3">
            <input 
              type="text" 
              value={inputMsg}
              onChange={(e) => setInputMsg(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSend()}
              placeholder="Send a test message..." 
              className="flex-1 bg-bg-elevated border border-border-strong text-text-primary rounded-md px-4 py-2 text-sm focus:outline-none focus:border-accent"
            />
            <button onClick={handleSend} disabled={!inputMsg.trim() || isTyping} className="h-10 px-4 rounded-md bg-accent text-white font-medium flex items-center justify-center shrink-0 disabled:opacity-50 transition-colors">
              <Send className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Right Panel: Trace Debugger */}
        <div className="flex-1 bg-[#1a1b26] flex flex-col font-mono text-sm relative overflow-hidden">
          <div className="bg-[#1f2335] text-[#a9b1d6] px-4 py-2 border-b border-[#292e42] flex justify-between items-center shrink-0 text-xs shadow-sm z-10">
            <span className="font-bold flex items-center gap-2"><TerminalSquare className="w-4 h-4 text-accent" /> BACKEND TRACE LOGS</span>
            <span className="text-[#565f89]">n8n Orchestration Pipeline</span>
          </div>
          
          <div className="flex-1 overflow-y-auto p-4 space-y-2 text-[13px] leading-relaxed">
            {logs.length === 0 ? (
              <div className="text-[#565f89] italic mt-4 text-center">Waiting for interactions... Send a message in the simulator to begin tracing logic.</div>
            ) : (
              logs.map(log => (
                <div key={log.id} className="flex items-start gap-4 hover:bg-white/5 p-1 rounded transition-colors -mx-1 px-1">
                  <div className="text-[#565f89] w-28 shrink-0">{log.timestamp}</div>
                  <div className={`flex-1 flex gap-2 ${getLogStyle(log.type)}`}>
                    {getLogIcon(log.type)}
                    <span className="break-words font-medium">{log.message}</span>
                  </div>
                </div>
              ))
            )}
            {isTyping && (
              <div className="flex items-start gap-4 p-1">
                 <div className="text-[#565f89] w-28 shrink-0">Processing</div>
                 <div className="flex-1 text-[#565f89] flex items-center gap-2"><div className="w-1.5 h-1.5 bg-[#a9b1d6] rounded-full animate-ping"></div> Awaiting LLM stream...</div>
              </div>
            )}
            <div ref={logsEndRef} />
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { useRouter } from "next/navigation";
import { useEffect } from "react";
import { useAuth } from "@/context/AuthContext";
import { Button } from "@/components/ui/Button";
import { LoadingSpinner } from "@/components/ui/Loading";

export default function LoginPage() {
  const { user, loading, signInWithGoogle } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!loading && user) {
      router.replace("/");
    }
  }, [user, loading, router]);

  async function handleSignIn() {
    try {
      await signInWithGoogle();
    } catch (err) {
      console.error(err);
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-bg-base flex items-center justify-center">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-bg-base flex">
      {/* Left ΓÇö branding panel */}
      <div className="hidden lg:flex flex-col justify-between w-[480px] flex-shrink-0 bg-bg-surface border-r border-border-subtle p-10">
        {/* Logo */}
        <div className="flex items-center gap-2.5">
          <div className="w-7 h-7 rounded-md bg-accent flex items-center justify-center">
            <span className="text-white text-sm font-bold">I</span>
          </div>
          <span className="font-semibold text-base text-text-primary tracking-tight">INFRIA</span>
        </div>

