"use client";

import { useTheme } from "next-themes";
import { useEffect, useState } from "react";
import { Moon, Sun } from "lucide-react";

export function ThemeToggle() {
  const { theme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return <div className="w-8 h-8 rounded-md bg-bg-elevated animate-pulse border border-border-default" />;
  }

  const isDark = theme === "dark";

  return (
    <button
      onClick={() => setTheme(isDark ? "light" : "dark")}
      className="flex items-center justify-center w-8 h-8 rounded-md text-text-secondary hover:text-text-primary 
        hover:bg-bg-hover transition-colors border border-transparent hover:border-border-default 
        focus:outline-none focus-visible:ring-2 focus-visible:ring-accent cursor-pointer"
      aria-label="Toggle theme"
    >
      {isDark ? (
        <Sun className="w-4 h-4 translate-y-[0px] duration-300" />
      ) : (
        <Moon className="w-4 h-4 translate-y-[0px] duration-300" />
      )}
    </button>
  );
}

import { AnalyticsMetrics, ActivityEntry, APIKey } from "@/types";
import { mockStore, generateApiKey, now } from "@/lib/mock-store";

const METRICS_KEY = (id: string) => `analytics_metrics_${id}`;
const ACTIVITY_KEY = (id: string) => `analytics_activity_${id}`;
const APIKEYS_KEY = (id: string) => `api_keys_${id}`;

function seedMetrics(projectId: string): AnalyticsMetrics {
  return {
    totalRequests: Math.floor(Math.random() * 2000) + 500,
    successfulRequests: Math.floor(Math.random() * 1800) + 400,
    failedRequests: Math.floor(Math.random() * 100) + 10,
    functionCalls: Math.floor(Math.random() * 500) + 50,
    fallbacks: Math.floor(Math.random() * 80) + 5,
    avgLatencyMs: Math.floor(Math.random() * 800) + 400,
  };
}

function seedActivity(projectId: string): ActivityEntry[] {
  const types: ActivityEntry["type"][] = ["chat", "function_call"];
  const fns = ["check_order_status", "get_appointment", "cancel_order"];
  const entries: ActivityEntry[] = [];
  for (let i = 0; i < 10; i++) {
    const type = types[Math.floor(Math.random() * types.length)];
    entries.push({
      id: `act_${i}`,
      projectId,
      timestamp: new Date(Date.now() - i * 90000).toISOString(),
      type,
      endpoint: type === "chat" ? "POST /v1/runtime/chat" : undefined,
      functionName:
        type === "function_call" ? fns[Math.floor(Math.random() * fns.length)] : undefined,
      status: Math.random() > 0.08 ? "success" : "error",
      latencyMs: Math.floor(Math.random() * 1500) + 200,
    });
  }
  return entries.sort(
    (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
  );
}

export const analyticsService = {
  async getMetrics(projectId: string): Promise<AnalyticsMetrics> {
    await delay(400);
    let metrics = mockStore.get<AnalyticsMetrics>(METRICS_KEY(projectId));
    if (!metrics) {
      metrics = seedMetrics(projectId);
      mockStore.set(METRICS_KEY(projectId), metrics);
    }
    return metrics;
  },

  async getActivity(projectId: string): Promise<ActivityEntry[]> {
    await delay(300);
    let activity = mockStore.getList<ActivityEntry>(ACTIVITY_KEY(projectId));
    if (activity.length === 0) {
      activity = seedActivity(projectId);
      mockStore.setList(ACTIVITY_KEY(projectId), activity);
    }
    return activity;
  },

  async getApiKeys(projectId: string): Promise<APIKey[]> {
    await delay(200);
    return mockStore.getList<APIKey>(APIKEYS_KEY(projectId));
  },

  async createApiKey(projectId: string, name: string): Promise<{ key: APIKey; rawKey: string }> {
    await delay(400);
    const rawKey = generateApiKey();
    const key: APIKey = {
      id: `key_${Date.now()}`,
      projectId,
      name,
      prefix: "infria_pk_",
      status: "active",
      createdAt: now(),
      lastUsed: null,
    };
    const existing = mockStore.getList<APIKey>(APIKEYS_KEY(projectId));
    existing.push(key);
    mockStore.setList(APIKEYS_KEY(projectId), existing);
    return { key, rawKey };
  },

  async revokeApiKey(projectId: string, keyId: string): Promise<void> {
    await delay(300);
    const keys = mockStore.getList<APIKey>(APIKEYS_KEY(projectId)).map((k) =>
      k.id === keyId ? { ...k, status: "revoked" as const } : k
    );
    mockStore.setList(APIKEYS_KEY(projectId), keys);
  },
};

function delay(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

"use client";

import {
  getDocs,
  addDoc,
  updateDoc,
} from "firebase/firestore";
import { auth } from "@/lib/firebase";
import { collection, doc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { APIKey } from "@/types";
import { now, generateApiKey, maskApiKey } from "@/lib/firestore-helpers";

function getUid(): string {
  const uid = auth.currentUser?.uid;
  if (!uid) throw new Error("User not authenticated");
  return uid;
}

function keysCol(projectId: string) {
  return collection(db, "users", getUid(), "projects", projectId, "api_keys");
}
function keyDoc(projectId: string, keyId: string) {
  return doc(db, "users", getUid(), "projects", projectId, "api_keys", keyId);
}

export const apiKeyService = {
  async list(projectId: string): Promise<APIKey[]> {
    const snap = await getDocs(keysCol(projectId));
    return snap.docs.map(d => ({ id: d.id, ...(d.data() as Omit<APIKey, "id">) }));
  },

  async generate(projectId: string, name: string): Promise<{ key: APIKey; rawKey: string }> {
    const rawKey = generateApiKey();
    const keyData = {
      projectId,
      name,
      prefix: rawKey.slice(0, 18) + "ΓÇóΓÇóΓÇóΓÇó",
      status: "active" as const,
      createdAt: now(),
      lastUsed: null,
    };
    const ref = await addDoc(keysCol(projectId), keyData);
    return { key: { id: ref.id, ...keyData }, rawKey };
  },

  async revoke(projectId: string, keyId: string): Promise<void> {
    await updateDoc(keyDoc(projectId, keyId), { status: "revoked" });
  },
};

"use client";

import {
  getDocs,
  getDoc,
  setDoc,
  deleteDoc,
  addDoc,
  updateDoc,
} from "firebase/firestore";
import { auth } from "@/lib/firebase";
import {
  knowledgeCol,
  knowledgeDoc,
  now,
} from "@/lib/firestore-helpers";
import { Knowledge, CreateKnowledgeInput } from "@/types";

function getUid(): string {
  const uid = auth.currentUser?.uid;
  if (!uid) throw new Error("User not authenticated");
  return uid;
}

export const knowledgeService = {
  async list(projectId: string): Promise<Knowledge[]> {
    const uid = getUid();
    const snap = await getDocs(knowledgeCol(uid, projectId));
    return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Omit<Knowledge, "id">) }));
  },

  async get(projectId: string, id: string): Promise<Knowledge> {
    const uid = getUid();
    const snap = await getDoc(knowledgeDoc(uid, projectId, id));
    if (!snap.exists()) throw new Error(`Knowledge not found: ${id}`);
    return { id: snap.id, ...(snap.data() as Omit<Knowledge, "id">) };
  },

  async createDraft(input: CreateKnowledgeInput): Promise<Knowledge> {
    const uid = getUid();
    const item = {
      projectId: input.projectId,
      title: input.title,
      category: input.category,
      content: input.content,
      status: "draft" as const,
      chunkCount: 0,
      createdAt: now(),
      updatedAt: now(),
    };
    const ref = await addDoc(knowledgeCol(uid, input.projectId), item);
    return { id: ref.id, ...item };
  },

  async publish(projectId: string, id: string): Promise<void> {
    const uid = getUid();
    await updateDoc(knowledgeDoc(uid, projectId, id), {
      status: "processing",
      updatedAt: now(),
    });
    // In production, a Cloud Function triggered by Firestore would handle vectorization.
    // For prototype, simulate with client-side timeout:
    setTimeout(async () => {
      const chunks = Math.floor(Math.random() * 15) + 3;
      await updateDoc(knowledgeDoc(uid, projectId, id), {
        status: "ready",
        chunkCount: chunks,
        updatedAt: now(),
      });
    }, 5000);
  },

  async update(projectId: string, id: string, updates: Partial<Knowledge>): Promise<void> {
    const uid = getUid();
    await updateDoc(knowledgeDoc(uid, projectId, id), { ...updates, updatedAt: now() });
  },

  async reindex(projectId: string, id: string): Promise<void> {
    const uid = getUid();
    await updateDoc(knowledgeDoc(uid, projectId, id), { status: "processing", updatedAt: now() });
    setTimeout(async () => {
      const chunks = Math.floor(Math.random() * 15) + 3;
      await updateDoc(knowledgeDoc(uid, projectId, id), {
        status: "ready",
        chunkCount: chunks,
        updatedAt: now(),
      });
    }, 4000);
  },

  async archive(projectId: string, id: string): Promise<void> {
    const uid = getUid();
    await updateDoc(knowledgeDoc(uid, projectId, id), { status: "archived", updatedAt: now() });
  },

  async delete(projectId: string, id: string): Promise<void> {
    const uid = getUid();
    await deleteDoc(knowledgeDoc(uid, projectId, id));
  },
};
